import {mountBattleSlice} from './battle-slice.js';
if(typeof document!=='undefined'&&document.getElementById('battleSlice'))mountBattleSlice(document.getElementById('battleSlice'),{scenario:(['fire','poison','eruption'].includes(new URLSearchParams(location.search).get('scenario'))?new URLSearchParams(location.search).get('scenario'):'fire')}).catch(error=>{document.getElementById('battleSlice').textContent='战斗试作尚未就绪：'+error.message;});
